-- private.member_take_window_facts(p_take uuid, p_team uuid)
CREATE OR REPLACE FUNCTION private.member_take_window_facts(p_take uuid, p_team uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  -- HD-3s-F2-F1 (PO decision CGR-289 (c)): what a hand-path rejection names about the take: its work date and its
  -- blocks (Europe/Zurich), and the home only when the take belongs to the team the hand command plans for (CGR-137:
  -- never another team's client). Facts of the order row only; nothing derived.
  select jsonb_strip_nulls(jsonb_build_object(
    'work_date', to_char(private.at_zurich(q.starts_at), 'YYYY-MM-DD'),
    'blocks', case when q.pause_starts_at is not null and q.pause_ends_at is not null
                   then to_char(private.at_zurich(q.starts_at), 'HH24:MI') || ' – '
                        || to_char(private.at_zurich(q.pause_starts_at), 'HH24:MI') || ' und '
                        || to_char(private.at_zurich(q.pause_ends_at), 'HH24:MI') || ' – '
                        || to_char(private.at_zurich(q.ends_at), 'HH24:MI')
                   else to_char(private.at_zurich(q.starts_at), 'HH24:MI') || ' – '
                        || to_char(private.at_zurich(q.ends_at), 'HH24:MI') end,
    'split', q.pause_starts_at is not null,
    'own_team', k.team_id = p_team,
    'client_name', case when k.team_id = p_team then a.display_name end))
  from public.order_takes k
  join public.partner_requests q on q.id = k.order_id
  left join public.client_accounts a on a.id = q.client_account_id
  where k.id = p_take
$function$;

revoke all on function private.member_take_window_facts(p_take uuid, p_team uuid) from public, anon, authenticated, service_role;
comment on function private.member_take_window_facts(p_take uuid, p_team uuid) is 'HD-3s-F2-F1 (CGR-289 (c)): work date and blocks of a take for a hand-path rejection; the home (client account name) only when the take belongs to p_team (CGR-137). Internal.';
